const canvas=document.getElementById("pixelCanvas"),ctx=canvas.getContext("2d");canvas.width=window.innerWidth*.6,canvas.height=Math.max(120,window.innerHeight*.12);let particles=[];function drawTextToCanvas(t){const n=document.createElement("canvas"),e=n.getContext("2d");return n.width=canvas.width,n.height=canvas.height,e.fillStyle="#fff",e.font="bold 10rem VT323",e.textAlign="left",e.textBaseline="middle",e.fillText(t,0,canvas.height/2),e.getImageData(0,0,canvas.width,canvas.height)}function createParticles(t){particles=[];const n=drawTextToCanvas(t);for(let e=0;e<n.height;e+=6)for(let a=0;a<n.width;a+=6)n.data[(e*n.width+a)*4+3]>128&&particles.push({x:a+Math.random()*10-5,y:e+Math.random()*10-5,targetX:a,targetY:e,vx:0,vy:0})}function animate(){ctx.clearRect(0,0,canvas.width,canvas.height),particles.forEach(t=>{t.vx+=(t.targetX-t.x)*.01,t.vy+=(t.targetY-t.y)*.01,t.vx*=.9,t.vy*=.9,t.x+=t.vx,t.y+=t.vy,ctx.fillStyle="#fff",ctx.fillRect(t.x,t.y,5,5)}),requestAnimationFrame(animate)}document.fonts.ready.then(()=>{createParticles("1nf1n0t1v3r"),animate()});
